    }
    tid {
        String _Unsigned "false";
        String long_name "GEBCO Type Identifier";
        Int16 valid_range -128, 127;
        Byte _FillValue 127;
        String flag_meanings "Land Singlebeam Multibeam Seismic Isolated_sounding ENC_sounding Lidar Optical Combined predicted_altimetry interpolated contour_charts contour_ENC bathymetric_sounding predicted_airborne iceberg_groundinggrounded_Argo_float_derived pre-generated_grid unknown steering_point";
