        String sdn_uom_name "Dimensionless";
        String sdn_uom_urn "SDN:P06:UUUU";
        Int32 units 1;
    }
    NC_GLOBAL {
        String comment "dataType IDentifier definitions\\n0 - Land\\n10 Singlebeam - depth value collected by a single beam echo-sounder\\n11 Multibeam - depth value collected by a multibeam echo-sounder\\n12 Seismic - depth value colleced by seismic methods\\n13 Isolated sounding - depth value that is not part of a regular survey or trackline\\n14 ENC sounding - depth value extracted from an Electronic Navigation Chart (ENC)\\n15 Lidar - depth derived from a bathymetric lidar sensor\\n16 Optical - Depth measured by optical light sensor\\n17 Combination of direct measurement methods\\nIn-direct Methods\\n40 Predicted based on satellite-derived gravity data - depth value is an interpolated value guided by satellite-derived gravity data\\n41 Interpolated based on a computer algorithm - depth value is an interpolated value based on a computer algorithm (e.g. Generic Mapping Tools)\\n42 Digital bathymetric contours from charts - depth value taken from a bathymetric contour data set\\n43 Digital bathymetric contours from ENCs - depth value taken from bathymetric contours from an Electronic Navigation Chart (ENC)\\n44 Bathymetric sounding - depth value at this location is constrained by bathymetric sounding(s) within a gridded data set where interpolation between sounding points is guided by satellite-derived gravity data\\n45 Predicted based on airborne (helicopter/flight)-derived gravity data\\n46 Depth estimated by calculating the draft of a grounded iceberg using satellite-derived freebord measurement\\nUnknown\\n47 Depth derived from grounded Argo float data\\n48 Depth measured by animal-borne data loggers\\n70 Pre-generated grid - depth value is taken from a pre-generated grid that is based on mixed source data types, e.g. single beam, multibeam, interpolation etc.\\n71 Unknown source - depth value from an unknown source\\n72 Steering points - depth value used to constrain the grid in areas of poor data coverage\\n";
        String Conventions "CF-1.6, ACDD-1.3";
        String creator_email "gdacc@seabed2030.org";
        String creator_name "GEBCO through the Nippon Foundation-GEBCO Seabed 2030 Project";
        String creator_type "International organisation";
        String creator_url "https://www.gebco.net";
        String date_created "2026-04-17";
        Int32 geospatial_bounds -180, -90, 180, 90;
        String geospatial_bounds_crs "WGS84";
        String geospatial_bounds_vertical_crs "EPSG:5831";
        Int32 geospatial_lat_max 90;
        Int32 geospatial_lat_min -90;
        Float64 geospatial_lat_resolution 0.004166666666666667;
        String geospatial_lat_units "degrees_north";
        Int32 geospatial_lon_max 180;
        Int32 geospatial_lon_min -180;
        Float64 geospatial_lon_resolution 0.004166666666666667;
        String geospatial_lon_units "degrees_east";
        String history "Fri Apr 17 15:55:53 2026: GDAL CreateCopy( GEBCO_2026_TID_CF_nodata_127.nc, ... )
Information on the development of the data set and the source data sets included in the grid can be found in the data set documentation available from https://www.gebco.net";
        String id "DOI: 10.5285/4f68d5c7-45eb-f999-e063-7086abc036f";
        String identifier_product_doi "DOI: 10.5285/4f68d5c7-45eb-f999-e063-7086abc036f";
